```python
import requests
import json

def extract_schema(graphql_url):
    """
    利用 GraphQL API 的内省查询漏洞，提取完整的 Schema。

    Args:
        graphql_url (str): GraphQL API 的 URL。

    Returns:
        dict: GraphQL Schema，如果成功；否则返回 None。
    """

    introspection_query = """
    query IntrospectionQuery {
      __schema {
        queryType {
          fields {
            name
            description
            args {
              name
              type
              defaultValue
              isRequired
            }
            type
          }
        }
        mutationType {
          fields {
            name
            description
            args {
              name
              type
              defaultValue
              isRequired
            }
            type
          }
        }
        subscriptionType {
          fields {
            name
            description
            args {
              name
              type
              defaultValue
              isRequired
            }
            type
          }
        }
        types {
          name
          description
          kind
          fields {
            name
            description
            args {
              name
              type
              defaultValue
              isRequired
            }
            type
          }
          interfaces {
            name
          }
          enumValues {
            name
            description
            deprecationReason
          }
        }
        directives {
          name
          description
          locations
          args {
            name
            type
            defaultValue
            isRequired
          }
        }
      }
    }
    """

    try:
        response = requests.post(graphql_url, json={'query': introspection_query})
        response.raise_for_status()  # 检查 HTTP 状态码

        data = response.json()

        if 'errors' in data:
            print("GraphQL API 返回错误：")
            print(data['errors'])
            return None

        schema = data['data']['__schema']
        return schema

    except requests.exceptions.RequestException as e:
        print(f"请求错误：{e}")
        return None
    except json.JSONDecodeError as e:
        print(f"JSON 解码错误：{e}")
        return None
    except KeyError as e:
        print(f"KeyError: {e}.  检查 GraphQL API 的响应格式是否符合预期。")
        return None


def main():
    """
    主函数，获取 GraphQL API URL 并提取 Schema。
    """
    graphql_url = input("请输入 GraphQL API 的 URL：")

    schema = extract_schema(graphql_url)

    if schema:
        print("GraphQL Schema：")
        print(json.dumps(schema, indent=2))
    else:
        print("无法提取 GraphQL Schema。")


if __name__ == "__main__":
    main()
```

**代码解释：**

1.  **`extract_schema(graphql_url)` 函数:**
    *   接收 GraphQL API 的 URL 作为输入。
    *   定义了一个 `introspection_query` 字符串，它是一个标准的 GraphQL 内省查询。  这个查询会请求 API 返回关于 Schema 的所有信息，包括类型、字段、参数、枚举值等。
    *   使用 `requests.post()` 发送 POST 请求到指定的 URL，并将内省查询作为 JSON 数据发送。
    *   `response.raise_for_status()` 检查 HTTP 状态码，如果状态码不是 200 OK，则会引发异常。
    *   使用 `response.json()` 将响应内容解析为 JSON。
    *   检查响应中是否存在 `errors` 字段。如果存在，则打印错误信息并返回 `None`。
    *   如果响应成功，则从 JSON 数据中提取 `__schema` 字段，它包含完整的 GraphQL Schema。
    *   使用 `json.dumps()` 将 Schema 格式化为易于阅读的 JSON 字符串，并打印到控制台。
    *   处理各种可能的异常，例如请求错误、JSON 解码错误和 `KeyError`（如果响应格式与预期不符）。

2.  **`main()` 函数:**
    *   提示用户输入 GraphQL API 的 URL。
    *   调用 `extract_schema()` 函数提取 Schema。
    *   如果 `extract_schema()` 返回了 Schema，则打印 Schema；否则，打印错误消息。

