**基本概念**

1.  **令牌 (Token):** Windows 安全系统的核心。每个进程都关联一个令牌，它包含进程的权限信息，例如用户身份、组 membership、特权等。
2.  **令牌模拟 (Token Impersonation):**  允许一个进程以另一个进程的身份运行，即复制目标进程的令牌。
3.  **创建进程 (CreateProcess):**  Windows API 函数，用于创建新的进程。在创建进程时，可以指定新进程使用的令牌。

**代码框架 (C++)**

```cpp
#include <iostream>
#include <windows.h>
#include <psapi.h> // for GetProcessHandleByProcessId

using namespace std;

// 函数：获取进程句柄
HANDLE GetProcessHandle(DWORD processId) {
    HANDLE hProcess = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, processId);
    if (hProcess == NULL) {
        cerr << "Error: OpenProcess failed. Error code: " << GetLastError() << endl;
        return NULL;
    }
    return hProcess;
}

// 函数：获取进程令牌
bool GetProcessToken(HANDLE hProcess, HANDLE* pToken) {
    if (OpenProcessToken(hProcess, TOKEN_QUERY, pToken) == FALSE) {
        cerr << "Error: OpenProcessToken failed. Error code: " << GetLastError() << endl;
        return false;
    }
    return true;
}

// 函数：复制令牌
bool DuplicateToken(HANDLE hToken, HANDLE hNewToken) {
    if (DuplicateTokenEx(hToken, NULL, TOKEN_DUPLICATE, FALSE, FALSE, NULL, hNewToken) == FALSE) {
        cerr << "Error: DuplicateTokenEx failed. Error code: " << GetLastError() << endl;
        return false;
    }
    return true;
}

// 函数：模拟令牌
bool ImpersonateToken(HANDLE hToken) {
    if (ImpersonateLoggedOnUser(hToken) == FALSE) {
        cerr << "Error: ImpersonateLoggedOnUser failed. Error code: " << GetLastError() << endl;
        return false;
    }
    return true;
}

int main() {
    // 1. 指定目标进程的 PID
    DWORD targetProcessId = 1234; // 替换为目标进程的实际 PID

    // 2. 获取目标进程的句柄
